const LD = colLetter(iD);
const P = {}; for (const h of ['pause', 'next_action', 'match_type', 'notes']) { const i = phdr.indexOf(h); if (i < 0) { throw new Error('ABORT: PIPELINE column missing ' + h); } P[h] = colLetter(i); }
// user 11 Sep: only Capital-A and Windrose are do-not-contact (inactive); debt investors get no matches
const INACTIVE = new Set(['capitala', 'windrosecapital']);
const DEBT_NAMES = new Set(['blacksoilcapitalformerlycaspiandebt', 'northernarc', 'coinagesolutionsdebt', 'debtworksdebt', 'strideventures', 'innovencapital', 'innovencapitaldebt', 'capwise', 'capwisedebt', 'epsilonxcapital', 'epsilonxcapitaldebt', 'aavishkarcapitaldebt', 'caspiandebt']);
const DEBT_RE = /\bdebt\b/i;
const debt = new Set(DEBT_NAMES);
for (const r of invRaw) { const k = nz(r.investor); if (!k) { continue; } if (DEBT_RE.test(s(r.investor)) || DEBT_RE.test(s(r.sector)) || DEBT_RE.test(s(r.stage))) { debt.add(k); } }
// 1. do_not_contact = Yes on Capital-A and Windrose
const invData = [], invLog = [], found = {};
for (const r of invRaw) { const k = nz(r.investor); if (!INACTIVE.has(k)) { continue; } found[k] = 1;
  if (s(r.do_not_contact).toLowerCase() !== 'yes') { invData.push({ range: 'INVESTORS!' + LD + r.row_number, values: [['Yes']] }); invLog.push({ investor: s(r.investor), row: r.row_number }); } }
for (const k of INACTIVE) { if (!found[k]) { throw new Error('ABORT: ' + k + ' not found in INVESTORS'); } }
// 2. PIPELINE: drop active deals of inactive + debt investors; retire debt HOLD rows
const pdata = [], drops = [], retired = [];
function note(p, t) { const n = s(p.notes); return (n ? n + ' | ' : '') + t; }
for (const p of pipe) {
