  const rn = p.row_number; const paused = s(p.pause).toLowerCase() === 'yes';
  if (!paused) {
    pdata.push({ range: 'PIPELINE!' + P.pause + rn, values: [['Yes']] }, { range: 'PIPELINE!' + P.next_action + rn, values: [['DROPPED - not per strategy']] },
      { range: 'PIPELINE!' + P.match_type + rn, values: [['Not per strategy: ' + why]] }, { range: 'PIPELINE!' + P.notes + rn, values: [[note(p, 'DROPPED 2026-09-11 - ' + why)]] });
    drops.push([rn, s(p.deal_id), s(p.startup), s(p.investor), why]);
  } else if (/^HOLD/i.test(s(p.next_action))) {
    pdata.push({ range: 'PIPELINE!' + P.next_action + rn, values: [['DROPPED - not per strategy']] }, { range: 'PIPELINE!' + P.match_type + rn, values: [['Not per strategy: ' + why]] });
    retired.push([rn, s(p.deal_id), s(p.startup), s(p.investor), why]);
  }
}
if (drops.length > 300) { throw new Error('ABORT: ' + drops.length + ' drops exceeds guard'); }
// 3. missing email / contact name / thesis, per investor
const NOTE = /meeting|deals shared|she say|follow up/i;
