for (const r of invRaw) { const n = s(r.investor); const k = nz(n);
  if (!k) { if (s(r.contact_person) || s(r.email)) { blankName.push({ row: r.row_number, contact: s(r.contact_person), email: s(r.email) }); } continue; }
  const x = agg[k] || (agg[k] = { investor: n, rows: [], email: '', contact: '', sector: '', stage: '', cheque: '', dnc: false });
  x.rows.push(r.row_number);
  if (!x.email && s(r.email)) { x.email = s(r.email); } if (!x.contact && s(r.contact_person)) { x.contact = s(r.contact_person); }
  const sv = s(r.sector), st = s(r.stage), ch = s(r.cheque_inr_cr);
  if (!x.sector && sv && !NOTE.test(sv)) { x.sector = sv; } if (!x.stage && st && !NOTE.test(st)) { x.stage = st; } if (!x.cheque && ch && !NOTE.test(ch)) { x.cheque = ch; }
  if (s(r.do_not_contact).toLowerCase() === 'yes' || INACTIVE.has(k)) { x.dnc = true; } }
const missing = [];
for (const k of Object.keys(agg)) { const x = agg[k]; const m = [];
  if (!x.email) { m.push('email'); } if (!x.contact) { m.push('contact name'); } if (!x.sector) { m.push('sector'); } if (!x.stage) { m.push('stage'); } if (!x.cheque) { m.push('cheque'); }
  if (m.length) { missing.push({ investor: x.investor, rows: x.rows.join(', '), missing: m.join(', '), email: x.email, contact: x.contact, sector: x.sector.slice(0, 70), stage: x.stage.slice(0, 40), cheque: x.cheque.slice(0, 30), dnc: x.dnc ? 'Yes' : '', debt: debt.has(k) ? 'Yes' : '' }); } }
if (!invData.length) { invData.push({ range: 'INVESTORS!' + LD + '1', values: [['do_not_contact']] }); }
if (!pdata.length) { pdata.push({ range: 'PIPELINE!' + P.pause + '1', values: [['pause']] }); }
const dncBefore = Object.keys(agg).filter(function (k) { return invRaw.some(function (r) { return nz(r.investor) === k && s(r.do_not_contact).toLowerCase() === 'yes'; }); }).map(function (k) { return agg[k].investor; });
return [{ json: { investors_distinct: Object.keys(agg).length, dnc_before_run: dncBefore, dnc_set: invLog, debt_investors: Array.from(debt).filter(function (k) { return agg[k]; }).map(function (k) { return agg[k].investor; }),
  drops: drops, retired_holds: retired, missing: missing, blank_name_rows: blankName, invData: invData, pdata: pdata } }];

